//! The shared Platform vector (`forge-contracts/fixtures/org/platform-v1.json`), generated by
//! `tools/org-vectors/gen.mjs platform` on the dti-2of3 ceremony.
#![allow(clippy::many_single_char_names)]

use std::collections::{BTreeMap, BTreeSet};

use serde_json::Value;
use sha2::{Digest, Sha256};

use super::canon::canonical;
use super::derive::{MemberKeys, Seed};
use super::request::{self, DocState, PartFacts, PartState, RequestStatus};
use super::state::{reduce, reduce_with, ProposalStatus};
use super::transport::{self, Carried, MemberDoc, MessageDoc, Roster};
use super::{bls, envelope, signing_ceremonies};
use crate::platform::FieldValue;

fn vector() -> Value {
    serde_json::from_str(include_str!(
        "../../../../forge-contracts/fixtures/org/platform-v1.json"
    ))
    .unwrap()
}

fn base() -> Value {
    serde_json::from_str(include_str!(
        "../../../../forge-contracts/fixtures/org/dti-2of3.json"
    ))
    .unwrap()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str()
        .unwrap_or_else(|| panic!("{k} is not a string"))
}

fn bytes(v: &Value, k: &str) -> Vec<u8> {
    hex::decode(s(v, k)).unwrap()
}

fn member_doc(d: &Value) -> MemberDoc {
    MemberDoc {
        id: s(d, "$id").into(),
        owner: s(d, "$ownerId").into(),
        created_at: d["$createdAt"].as_u64().unwrap(),
        org: s(d, "org").into(),
        auth_pub: bytes(d, "authPub"),
        proof: bytes(d, "proof"),
    }
}

fn message_doc(d: &Value) -> MessageDoc {
    MessageDoc {
        id: s(d, "$id").into(),
        owner: s(d, "$ownerId").into(),
        created_at: d["$createdAt"].as_u64().unwrap(),
        digest: bytes(d, "digest"),
        part: d["part"].as_u64().unwrap(),
        parts: d["parts"].as_u64().unwrap(),
        fmt: d["fmt"].as_u64().unwrap(),
        body: bytes(d, "body"),
    }
}

fn ids(carried: &[Carried]) -> Vec<String> {
    carried
        .iter()
        .map(|c| envelope::id(&c.envelope).unwrap())
        .collect()
}

#[test]
fn member_seeds_proofs_and_sealed_shares_match() {
    let v = vector();
    let b = base();
    let (network, org, cid) = (s(&v, "network"), s(&v, "orgId"), s(&v, "cid"));
    for (m, bm) in v["members"]
        .as_array()
        .unwrap()
        .iter()
        .zip(b["members"].as_array().unwrap())
    {
        let from_phrase = Seed::from_phrase(s(bm, "mnemonic"), s(bm, "passphrase")).unwrap();
        assert_eq!(hex::encode(from_phrase.bytes()), s(m, "seed"));
        let keys = MemberKeys::derive(&from_phrase);
        assert_eq!(keys.auth_pub, s(m, "authPub"));
        let owner = s(m, "ownerId");
        assert_eq!(
            transport::proof_message(network, org, owner),
            s(m, "proofMessage")
        );
        let proof = transport::member_proof(&keys, network, org, owner);
        assert_eq!(hex::encode(proof), s(m, "proof"));
        assert!(transport::verify_proof(
            &bytes(m, "authPub"),
            network,
            org,
            owner,
            &proof
        ));
        assert!(!transport::verify_proof(
            &bytes(m, "authPub"),
            network,
            org,
            org,
            &proof
        ));

        let share = bls::parse_share(s(m, "share")).unwrap();
        let sealed = bytes(m, "sealedShare");
        let nonce: [u8; 24] = sealed[..24].try_into().unwrap();
        assert_eq!(
            transport::seal_share(&from_phrase, network, org, cid, &share, nonce),
            sealed
        );
        assert_eq!(
            transport::open_share(&from_phrase, network, org, cid, &sealed),
            Some(share)
        );
    }
    for c in v["sealedShares"].as_array().unwrap() {
        let seed = Seed::from_bytes(bytes(c, "seed").try_into().unwrap());
        let got = transport::open_share(
            &seed,
            s(c, "network"),
            s(c, "org"),
            cid,
            &bytes(c, "sealed"),
        );
        let want = c["share"].as_str().map(|h| bls::parse_share(h).unwrap());
        assert_eq!(got, want, "{}", s(c, "name"));
    }
}

#[test]
fn member_identities_bind_as_the_vector_says() {
    let v = vector();
    let docs: Vec<MemberDoc> = v["memberDocs"]
        .as_array()
        .unwrap()
        .iter()
        .map(member_doc)
        .collect();
    let members: BTreeSet<String> = v["members"]
        .as_array()
        .unwrap()
        .iter()
        .map(|m| s(m, "authPub").to_string())
        .collect();
    let bound = transport::bind_identities(&docs, s(&v, "network"), s(&v, "orgId"), &members);
    let got: BTreeMap<String, Vec<String>> = bound
        .into_iter()
        .map(|(k, ds)| (k, ds.into_iter().map(|d| d.owner.clone()).collect()))
        .collect();
    let want: BTreeMap<String, Vec<String>> =
        serde_json::from_value(v["boundIdentities"].clone()).unwrap();
    assert_eq!(got, want);
}

#[test]
fn the_roster_matches_the_ceremony_and_stands_in_for_it() {
    let v = vector();
    let b = base();
    let state = reduce(
        b["ceremonyMessages"].as_array().unwrap(),
        b["room"].as_str(),
    );
    let c = signing_ceremonies(&state)[0];
    let r = &v["roster"];
    let props = BTreeMap::from([
        ("room".to_string(), FieldValue::text(s(r, "room"))),
        ("relay".to_string(), FieldValue::text(s(r, "relay"))),
        ("cid".to_string(), FieldValue::Bytes(bytes(r, "cid"))),
        (
            "keyId".to_string(),
            FieldValue::Integer(r["keyId"].as_u64().unwrap()),
        ),
        (
            "groupKey".to_string(),
            FieldValue::Bytes(bytes(r, "groupKey")),
        ),
        (
            "threshold".to_string(),
            FieldValue::Integer(r["threshold"].as_u64().unwrap()),
        ),
        (
            "members".to_string(),
            FieldValue::Bytes(bytes(r, "members")),
        ),
        (
            "pubShares".to_string(),
            FieldValue::Bytes(bytes(r, "pubShares")),
        ),
    ]);
    let from_doc = Roster::from_props(&props).unwrap();
    assert_eq!(from_doc.props(), props);
    let of_ceremony = Roster::of_ceremony(c, Some("https://multisig.dashhq.org")).unwrap();
    assert_eq!(from_doc, of_ceremony);
    assert_eq!(hex::encode(from_doc.members_bytes()), s(r, "members"));
    assert_eq!(hex::encode(from_doc.pub_shares_bytes()), s(r, "pubShares"));

    // With only the roster, the merged log reduces to the same proposal states.
    let timed = merged(&v);
    let stand_in = from_doc.ceremony("testnet", "acme");
    let from_roster = reduce_with(&[], &timed, Some(s(&v, "room")), vec![stand_in]);
    let from_transcript = reduce_with(
        b["ceremonyMessages"].as_array().unwrap(),
        &timed,
        Some(s(&v, "room")),
        Vec::new(),
    );
    for (id, p) in &from_transcript.proposals {
        let q = &from_roster.proposals[id];
        assert_eq!(p.status, q.status, "{id}");
        assert_eq!(
            p.requirements[0].shares.keys().collect::<Vec<_>>(),
            q.requirements[0].shares.keys().collect::<Vec<_>>()
        );
    }
}

#[test]
fn messages_split_deflate_and_reassemble() {
    let v = vector();
    for c in v["messages"].as_array().unwrap() {
        let name = s(c, "name");
        let parts: Vec<Vec<u8>> = c["parts"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| hex::decode(p.as_str().unwrap()).unwrap())
            .collect();
        let payload = parts.concat();
        assert_eq!(
            hex::encode(Sha256::digest(&payload)),
            s(c, "digest"),
            "{name}"
        );
        let env = transport::decode(c["fmt"].as_u64().unwrap(), &payload).unwrap();
        assert_eq!(
            canonical(&env).unwrap(),
            canonical(&c["envelope"]).unwrap(),
            "{name}"
        );
        assert_eq!(envelope::id(&env).unwrap(), s(c, "id"));
        assert!(parts.iter().all(|p| p.len() <= transport::MAX_PART));

        let ours = transport::encode(&c["envelope"]).unwrap();
        assert_eq!(
            u64::from(ours.fmt),
            c["writerFmt"].as_u64().unwrap(),
            "{name}"
        );
        let back = transport::decode(u64::from(ours.fmt), &ours.parts.concat()).unwrap();
        assert_eq!(back, c["envelope"]);
        if c["fmt"] == 0 {
            let raw = transport::decode(0, &payload)
                .map(|e| canonical(&e).unwrap())
                .unwrap();
            assert_eq!(raw.len() as u64, c["canonicalLength"].as_u64().unwrap());
        }
    }
}

#[test]
fn reassembly_takes_whole_messages_only() {
    let v = vector();
    for c in v["reassembly"].as_array().unwrap() {
        let docs: Vec<MessageDoc> = c["docs"]
            .as_array()
            .unwrap()
            .iter()
            .map(message_doc)
            .collect();
        let want: Vec<String> = serde_json::from_value(c["accepted"].clone()).unwrap();
        assert_eq!(ids(&transport::reassemble(&docs)), want, "{}", s(c, "name"));
    }
}

fn merged(v: &Value) -> Vec<transport::Timed> {
    let m = &v["merge"];
    let docs: Vec<MessageDoc> = m["docs"]
        .as_array()
        .unwrap()
        .iter()
        .map(message_doc)
        .collect();
    let mut owner_keys: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for (k, os) in m["boundOwners"].as_object().unwrap() {
        for o in os.as_array().unwrap() {
            owner_keys
                .entry(o.as_str().unwrap().to_string())
                .or_default()
                .insert(k.clone());
        }
    }
    transport::merge(&transport::reassemble(&docs), &owner_keys)
}

#[test]
fn merge_orders_dedupes_and_ignores_carried_copies() {
    let v = vector();
    let b = base();
    let m = &v["merge"];
    let timed = merged(&v);
    let order: Vec<String> = serde_json::from_value(m["order"].clone()).unwrap();
    assert_eq!(
        timed.iter().map(|t| t.id.clone()).collect::<Vec<_>>(),
        order
    );
    for t in &timed {
        assert_eq!(t.at, s(&m["at"], &t.id));
    }
    let state = reduce_with(
        b["ceremonyMessages"].as_array().unwrap(),
        &timed,
        Some(s(&v, "room")),
        Vec::new(),
    );
    let e = &m["expected"];
    let a = &state.proposals[s(&e["requestA"], "proposal")];
    assert_eq!(a.status, ProposalStatus::Ready);
    assert_eq!(s(&e["requestA"], "status"), "ready");
    let shares: Vec<u64> = a.requirements[0]
        .shares
        .keys()
        .map(|k| u64::from(*k))
        .collect();
    assert_eq!(
        shares,
        serde_json::from_value::<Vec<u64>>(e["requestA"]["shares"].clone()).unwrap()
    );
    let big = &state.proposals[s(&e["big"], "proposal")];
    assert_eq!(big.status, ProposalStatus::Collecting);
    let rejected: Vec<String> = big.rejections.keys().cloned().collect();
    assert_eq!(
        rejected,
        serde_json::from_value::<Vec<String>>(e["big"]["rejections"].clone()).unwrap()
    );
    assert_eq!(a.at, s(&m["at"], s(&e["requestA"], "proposal")));
}

#[test]
fn request_ids_name_their_proposer() {
    let v = vector();
    let b = base();
    let r = &v["requestIds"];
    let mut msgs: Vec<Value> = b["ceremonyMessages"].as_array().unwrap().clone();
    msgs.extend(r["envelopes"].as_array().unwrap().iter().cloned());
    let state = reduce(&msgs, b["room"].as_str());
    let reqs = request::requests(&state, s(&v, "cid"));
    let mut got: Vec<(String, String, Vec<String>, bool)> = reqs
        .iter()
        .map(|q| {
            (
                q.id.clone(),
                q.proposer.clone(),
                q.proposals.clone(),
                q.forge,
            )
        })
        .collect();
    got.sort();
    let mut want: Vec<(String, String, Vec<String>, bool)> = r["requests"]
        .as_array()
        .unwrap()
        .iter()
        .map(|q| {
            (
                s(q, "id").to_string(),
                s(q, "proposer").to_string(),
                serde_json::from_value(q["proposals"].clone()).unwrap(),
                q["forge"].as_bool().unwrap(),
            )
        })
        .collect();
    want.sort();
    assert_eq!(got, want);
    for c in r["resolve"].as_array().unwrap() {
        assert_eq!(
            request::find(&reqs, s(c, "query")).map(|q| q.id.as_str()),
            c["id"].as_str(),
            "{}",
            s(c, "query")
        );
    }
}

#[test]
fn status_follows_the_table() {
    let v = vector();
    let st = &v["status"];
    let (n, m) = (
        usize::try_from(st["threshold"].as_u64().unwrap()).unwrap(),
        usize::try_from(st["size"].as_u64().unwrap()).unwrap(),
    );
    for c in st["cases"].as_array().unwrap() {
        let name = s(c, "name");
        let parts: Vec<(bool, PartState)> = c["parts"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| {
                let ready = p["shares"].as_u64().unwrap() >= n as u64;
                let facts = PartFacts {
                    nonce_spent: p["nonceSpent"].as_bool().unwrap(),
                    doc: match s(p, "doc") {
                        "absent" => DocState::Absent,
                        "present" => DocState::Present,
                        "same" => DocState::Same,
                        "different" => DocState::Different,
                        "later" => DocState::Later,
                        "base" => DocState::Base,
                        other => panic!("{other}"),
                    },
                    taken_by_other: p["takenByOther"].as_bool().unwrap(),
                };
                let state = request::part_state(
                    s(p, "action"),
                    ready,
                    p["claim"].as_bool().unwrap(),
                    Some(&facts),
                );
                (ready, state)
            })
            .collect();
        let problems: Vec<String> = c
            .get("problems")
            .map(|p| serde_json::from_value(p.clone()).unwrap())
            .unwrap_or_default();
        let declined = usize::try_from(c["declined"].as_u64().unwrap_or(0)).unwrap();
        let sum = request::summarize(problems, declined, n, m, &parts);
        let want_parts: Vec<PartState> =
            serde_json::from_value(c["expect"]["parts"].clone()).unwrap();
        assert_eq!(sum.parts, want_parts, "{name}");
        let want_status: RequestStatus =
            serde_json::from_value(c["expect"]["status"].clone()).unwrap();
        assert_eq!(sum.status, want_status, "{name}");
        assert_eq!(
            sum.text().as_deref(),
            c["expect"]["text"].as_str(),
            "{name}"
        );
    }
}
